const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=n=>new Intl.NumberFormat('fr-FR').format(n)+' FCFA';
const eventDate=e=>new Date(e.id==='openair'?'2026-10-10':e.id==='jazz'?'2026-11-14':e.id==='ocean'?'2026-11-08':e.id==='design'?'2026-11-22':e.id==='afro'?'2026-12-05':e.id==='teranga'?'2026-12-12':'2026-12-27T18:00:00');
const eventCityKey=e=>e.city.toLowerCase().includes('dakar')?'Dakar':e.city.toLowerCase().includes('saly')?'Saly':e.city.toLowerCase().includes('dagana')?'Dagana':'Thiès';
const attendees=[{id:'FD-WALO-001',name:'Fatou Ndiaye',email:'fatou.ndiaye@example.com',event:'WALO UP 2026',type:'Standard',amount:30000,status:'Valide'},{id:'FD-WALO-002',name:'Moussa Diop',email:'moussa.diop@example.com',event:'WALO UP 2026',type:'Navette',amount:35000,status:'Valide'},{id:'FD-WALO-003',name:'Aminata Sarr',email:'aminata.sarr@example.com',event:'WALO UP 2026',type:'Standard',amount:30000,status:'Scanné'},{id:'FD-JAZZ-001',name:'Ibrahima Ba',email:'ibrahima.ba@example.com',event:'Dakar en Jazz',type:'VIP',amount:45000,status:'Valide'},{id:'FD-OPEN-001',name:'Marième Fall',email:'marieme.fall@example.com',event:'Dakar Open Air',type:'Standard',amount:18000,status:'Valide'}];
function discoveryMatches(e){const q=`${e.name} ${e.city} ${e.category}`.toLowerCase();if(!(s.filter==='Tout'||e.category===s.filter)||!q.includes(s.query.toLowerCase()))return false;if(s.city!=='Toutes les villes'&&eventCityKey(e)!==s.city)return false;if(s.maxBudget<100000&&e.price>s.maxBudget)return false;if(s.dateRange==='Cette semaine'){const days=(eventDate(e)-new Date())/86400000;if(days<0||days>7)return false}if(s.dateRange==='Ce mois-ci'){const now=new Date(),d=eventDate(e);if(d.getMonth()!==now.getMonth()||d.getFullYear()!==now.getFullYear())return false}return true}
function runEventFinder(text){const q=text.toLowerCase();const city=/dakar/.test(q)?'Dakar':/saly/.test(q)?'Saly':/dagana/.test(q)?'Dagana':null;const budgetMatch=q.match(/(\d[\d\s.,]*\s*(?:k|000)?)\s*(?:fcfa|f\b)/i);let budget=budgetMatch?Number(budgetMatch[1].toLowerCase().replace(/[\s.,]/g,'').replace(/k$/,'000')):null;if(budgetMatch&&/k/i.test(budgetMatch[1]))budget=Number(budgetMatch[1].replace(/[\s.,k]/gi,''))*1000;const genre=/festival|musique|concert|music/.test(q);let list=events.filter(e=>(!city||eventCityKey(e)===city)&&(!genre||/festival|musique/i.test(e.category+' '+e.name))&&(!budget||e.price<=budget));if(/week.?end|samedi|dimanche/.test(q)){const now=new Date(),next=(6-now.getDay()+7)%7||7,start=new Date(now);start.setDate(now.getDate()+next);const end=new Date(start);end.setDate(start.getDate()+1);list=list.filter(e=>eventDate(e)>=start&&eventDate(e)<=end)}if(!list.length)list=events.filter(e=>(!city||eventCityKey(e)===city)&&(!genre||/festival|musique/i.test(e.category+' '+e.name))).sort((a,b)=>Math.abs(a.price-(budget||20000))-Math.abs(b.price-(budget||20000))).slice(0,2);s.aiResults=list.map(e=>e.id);s.aiQuery=text;s.aiExplanation=list.length?`J’ai retenu ${list.length} idée${list.length>1?'s':''}${city?` à ${city}`:''}${budget?` autour de votre budget de ${money(budget)}`:''}. La sélection privilégie les événements qui correspondent à vos envies et à leur disponibilité.`:'Aucun événement ne correspond exactement. Essayez une autre ville ou un budget différent.';render();document.querySelector('#ai-results')?.scrollIntoView({behavior:'smooth',block:'center'})}
function qrMarkup(code){let seed=Array.from(code).reduce((a,c)=>a+c.charCodeAt(0),0);const cells=Array.from({length:441},(_,i)=>{seed=(seed*9301+49297)%233280;const x=i%21,y=Math.floor(i/21),finder=(ox,oy)=>x>=ox&&x<ox+7&&y>=oy&&y<oy+7&&((x===ox||x===ox+6||y===oy||y===oy+6)||(x>=ox+2&&x<=ox+4&&y>=oy+2&&y<=oy+4));return finder(0,0)||finder(14,0)||finder(0,14)||seed/233280>.55?'1':'0'}).join('');return `<div class="qr-grid" role="img" aria-label="QR code de démonstration">${[...cells].map(v=>`<i class="${v==='1'?'dark':''}"></i>`).join('')}</div>`}
function ticketHub(){const favs=events.filter(e=>s.favoriteIds.includes(e.id));const bought=events.filter(e=>s.purchases.includes(e.id));return `<div class="wrap">${header()}<section class="personal-head"><div class="eyebrow">VOTRE ESPACE PERSONNEL</div><h1>Les bons moments vous attendent.</h1><p>Vos billets, vos envies, et les sorties déjà partagées.</p></section><div class="ticket-tabs">${['À venir','Favoris','Historique','Calendrier'].map(t=>`<button class="${s.ticketTab===t?'active':''}" data-ticket-tab="${t}">${t==='Favoris'?'♡ ':''}${t}</button>`).join('')}</div>${s.ticketTab==='Favoris'?`<section class="events-grid personal-events">${favs.length?favs.map(card).join(''):'<div class="empty-state">Pas encore de favoris. Gardez un œil sur les événements qui vous tentent.</div>'}</section>`:s.ticketTab==='Historique'?`<section class="pro-card history-list"><h2>Vos réservations</h2>${bought.map(e=>`<div class="event-row"><div class="event-thumb" style="background-image:url('${e.img}')"></div><div class="event-row-main"><strong>${e.name}</strong><small>${e.day} ${e.month} ${e.year} · ${e.city}</small></div><span class="badge">Confirmé</span><button class="quiet" data-ticket-open="${e.id}">Voir le billet ↗</button></div>`).join('')||'<p class="muted">Votre historique de réservations s’affichera ici.</p>'}</section>`:s.ticketTab==='Calendrier'?`<section class="calendar-card"><div class="section-head"><div><div class="eyebrow">OCTOBRE — DÉCEMBRE 2026</div><h2>Votre calendrier vivant.</h2></div><button class="dark-button" data-calendar-export>Exporter mon calendrier ↗</button></div><div class="calendar-grid">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<b class="calendar-dayname">${x}</b>`).join('')}${Array.from({length:35},(_,i)=>`<div class="calendar-cell"><small>${i+1}</small>${[10,27].includes(i+1)?`<span class="calendar-dot">${i+1===10?'Dakar Open Air':'Walo Festival'}</span>`:''}</div>`).join('')}</div></section>`:`<section class="ticket-list">${bought.map(e=>{const code=`FOD-${e.id.toUpperCase()}-0001`;return `<article class="digital-ticket"><div class="ticket-left"><span class="tag">${s.validatedTicket===e.id?'Entrée validée':'Billet confirmé'}</span><h2>${e.name}</h2><p>${e.day} ${e.month} ${e.year} · 18:00</p><p>⌖ &nbsp;${e.city} · Entrée générale</p><div class="ticket-code-text">${code}</div><div class="ticket-actions"><button class="lime-button" data-ticket-validate="${e.id}">${s.validatedTicket===e.id?'✓ Billet validé':'Simuler la validation'}</button><button class="pill-button" data-ticket-share="${e.id}">Inviter des amis ↗</button></div></div><div class="ticket-right">${qrMarkup(code)}<small>QR de démonstration · non scannable</small></div></article>`}).join('')||'<div class="empty-state">Aucun billet à venir pour le moment.<br><button class="dark-button" data-view="home" style="margin-top:15px">Explorer les événements</button></div>'}</section>`}</div>${nav('Mes billets')}`}
function calendarPage(){const bought=events.filter(e=>s.purchases.includes(e.id));const months=[10,11,12];return `<div class="wrap">${header()}<section class="personal-head"><div class="eyebrow">VOTRE CALENDRIER</div><h1>Les sorties déjà réservées.</h1><p>Vos événements confirmés, rangés par date.</p><button class="dark-button" data-calendar-export>Exporter mon calendrier ↗</button></section><div class="ticket-tabs">${['À venir','Favoris','Historique','Calendrier'].map(t=>`<button class="${s.ticketTab===t?'active':''}" data-ticket-tab="${t}">${t==='Favoris'?'♡ ':''}${t}</button>`).join('')}</div><section class="calendar-months">${months.map(month=>{const first=new Date(2026,month-1,1),offset=(first.getDay()+6)%7,count=new Date(2026,month,0).getDate();return `<article class="calendar-card"><div class="eyebrow">${first.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</div><div class="calendar-grid">${['L','M','M','J','V','S','D'].map(x=>`<b class="calendar-dayname">${x}</b>`).join('')}${Array.from({length:offset+count},(_,i)=>{const day=i-offset+1,e=i<offset?null:bought.find(x=>eventDate(x).getMonth()===month-1&&eventDate(x).getDate()===day);return `<div class="calendar-cell ${e?'has-event':''}"><small>${i<offset?'':day}</small>${e?`<button class="calendar-dot" data-ticket-open="${e.id}">${e.name}</button>`:''}</div>`}).join('')}</div></article>`}).join('')}${bought.length?'':'<div class="empty-state">Aucune réservation dans ces mois pour le moment.</div>'}</section></div>${nav('Mes billets')}`}
function augmentPublic(markup){if(s.view==='home')return publicEnhancements(markup);if(s.view==='event'){markup=markup.replace('</h1><div class="detail-facts">',`</h1><button class="favorite-toggle ${s.favoriteIds.includes(s.event)?'saved':''}" data-favorite-toggle="${s.event}">${s.favoriteIds.includes(s.event)?'♥ Enregistré':'♡ Ajouter aux favoris'}</button><div class="detail-facts">`);markup=markup.replace('</aside></main>',`<div class="join-vibe"><div><b>La vibe est meilleure à plusieurs.</b><small>Créez un petit groupe et retrouvez vos amis sur place.</small></div><button class="pill-button" data-join-vibe>＋ Inviter mes amis</button></div></aside></main>`);markup=markup.replace('</div><div style="margin-top:19px">','</div><div class="gallery-caption"><span>UNE SOIRÉE QUI SE VIT ENSEMBLE</span><span>01 / 03</span></div><div style="margin-top:19px">')}return markup}
function proEnhancements(markup){if(s.proPage==='home'||s.proPage==='events'){markup=markup.replace('<div class="pro-greeting">',`<div class="pro-toolstrip"><button data-propage="create">＋ Créer un événement</button><button data-propage="attendees">♙ Participants</button><button data-propage="checkin">⌗ Contrôle QR</button><button data-propage="insights">✦ Insights</button></div><div class="pro-greeting">`)}if(s.proPage==='dashboard'){const scale=(s.period==='7 jours'?.42:s.period==='90 jours'?2.45:1)*(s.analyticsCategory==='Tous'?1:s.analyticsCategory==='Festival'?.58:.32);markup=markup.replace('<span class="badge">Cette année</span>','<span class="badge">Données interactives</span>');markup=markup.replace('<div class="chart">',`<div class="analytics-controls"><label>Période<select data-analytics="period">${['7 jours','30 jours','90 jours'].map(x=>`<option ${s.period===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Catégorie<select data-analytics="category">${['Tous','Festival','Musique','Culture'].map(x=>`<option ${s.analyticsCategory===x?'selected':''}>${x}</option>`).join('')}</select></label><span class="insight-note">✦ Festivals +34 % ce mois-ci</span><button class="quiet" data-propage="insights">Voir les insights ↗</button></div><div class="chart">`);markup=markup.replace('3 325 000 F',money(Math.round(3325000*scale))).replace('1 343',new Intl.NumberFormat('fr-FR').format(Math.round(1343*scale))).replace('68 %',`${Math.min(98,Math.round(68*scale))} %`).replace('624',new Intl.NumberFormat('fr-FR').format(Math.round(624*scale)));const i=markup.indexOf('<div class="chart">'),j=markup.indexOf('</section>',i);if(i>0&&j>i){const heights=s.period==='7 jours'?[21,33,29,49,45,62,53,76]:s.period==='90 jours'?[44,55,61,67,74,81,87,95]:[30,45,38,57,49,75,63,92];let n=0;markup=markup.slice(0,i)+markup.slice(i,j).replace(/height:\d+%/g,()=>`height:${Math.round(heights[n++%heights.length]*(s.analyticsCategory==='Tous'?1:s.analyticsCategory==='Festival'?.8:.55))}%`)+markup.slice(j)}}return markup}
function publicEnhancements(markup){if(s.view==='home'){const featured=events.find(e=>e.id==='openair');const next=events.find(e=>e.id==='walo');markup=markup.replace('</div></section><section class="shortcuts">',`<div class="hero-event-stack"><button class="hero-event main" data-event="${featured.id}" style="background-image:url('${featured.img}')"><span>À LA UNE · ${featured.date}</span><b>${featured.name}</b><small>${featured.city} · ${money(featured.price)}</small></button><button class="hero-event mini" data-event="${next.id}"><span>À VENIR</span><b>${next.name}</b><small>${next.day} ${next.month} · ${next.city}</small></button></div></section><section class="shortcuts">`);markup=markup.replace('<main class="discover"',`<section class="event-finder" id="event-finder"><div class="finder-copy"><span class="finder-mark">✦</span><div><div class="eyebrow">FODIUM AI · EVENT FINDER</div><h2>Trouvons votre prochaine sortie.</h2><p>Racontez-nous l’ambiance, la ville et le budget. On cherche dans les événements disponibles.</p></div></div><div class="finder-input"><input id="ai-query" value="${escapeHtml(s.aiQuery)}" placeholder="Ex. Festival de musique à Dakar ce week-end, 20 000 FCFA"><button class="lime-button" data-ai-search>✦ Trouver mon événement</button></div>${s.aiResults.length?`<div class="finder-results" id="ai-results"><p>${s.aiExplanation}</p><div class="finder-cards">${s.aiResults.map(id=>events.find(e=>e.id===id)).filter(Boolean).map(card).join('')}</div></div>`:''}</section><main class="discover"`);markup=markup.replace('</div><div class="events-grid">',`</div><div class="discovery-controls"><label>Ville<select data-discovery="city"><option>Toutes les villes</option>${['Dakar','Saly','Dagana','Thiès'].map(v=>`<option ${s.city===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Date<select data-discovery="date"><option>Toutes les dates</option><option ${s.dateRange==='Cette semaine'?'selected':''}>Cette semaine</option><option ${s.dateRange==='Ce mois-ci'?'selected':''}>Ce mois-ci</option></select></label><label>Budget<select data-discovery="budget"><option value="100000">Tous les budgets</option><option value="10000" ${s.maxBudget===10000?'selected':''}>Jusqu’à 10 000 F</option><option value="20000" ${s.maxBudget===20000?'selected':''}>Jusqu’à 20 000 F</option><option value="30000" ${s.maxBudget===30000?'selected':''}>Jusqu’à 30 000 F</option></select></label><label>Trier<select data-discovery="sort"><option>Tendance</option><option ${s.sort==='Date'?'selected':''}>Date</option><option ${s.sort==='Price'?'selected':''}>Prix</option></select></label><button class="quiet map-trigger" data-map-toggle>${s.mapOpen?'Vue liste':'⌖ Voir autour de moi'}</button></div><div class="events-grid">`);const recs=(s.favoriteIds.length?events.filter(e=>s.favoriteIds.some(id=>events.find(x=>x.id===id)?.category===e.category)):events.filter(e=>e.category==='Festival')).slice(0,3);markup=markup.replace('</div></main><footer class="footer">',`</div><section class="recommendations"><div class="section-head"><div><div class="eyebrow">CHOISI POUR VOUS</div><h2>Recommended for you.</h2><p class="muted">${s.favoriteIds.length?'Basé sur vos événements favoris.':'Une sélection pour commencer à explorer.'}</p></div><button class="quiet" data-view="tickets">Vos favoris ♡</button></div><div class="events-grid">${recs.map(card).join('')}</div></section>${s.mapOpen?`<section class="around-map"><div><div class="eyebrow">DISCOVER AROUND YOU</div><h2>La ville se met en mouvement.</h2><label>Afficher à <select data-map-city>${['Dakar','Saly','Dagana'].map(v=>`<option ${s.city===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="mock-map">${events.filter(e=>s.city==='Toutes les villes'||eventCityKey(e)===s.city).map((e,i)=>`<button class="map-pin pin-${i%5}" data-event="${e.id}"><span>↗</span><b>${e.name}</b><small>${money(e.price)}</small></button>`).join('')}<span class="map-water">SÉNÉGAL</span></div></section>`:''}</main><footer class="footer">`)}return markup}
const s={view:'home',event:'walo',bundle:false,departure:'Dakar — Liberté 6',payment:'Wave',proPage:'home',modal:'',query:'',filter:'Tout',ticket:false,lang:localStorage.getItem('fodium-lang')||'fr',dark:localStorage.getItem('fodium-dark')==='true',chatOpen:false,chatMessages:[],favoriteIds:JSON.parse(localStorage.getItem('fodium-favorites')||'["jazz","openair"]'),purchases:JSON.parse(localStorage.getItem('fodium-purchases')||'["walo"]'),city:'Toutes les villes',dateRange:'Toutes les dates',maxBudget:100000,sort:'Tendance',mapOpen:false,aiQuery:'',aiResults:[],aiExplanation:'',ticketTab:'À venir',wizardStep:1,draft:{name:'',city:'Dakar',date:'2026-12-27',category:'Festival',price:15000,capacity:500},attendeeSearch:'',attendeeFilter:'Tous',period:'30 jours',analyticsCategory:'Tous',scanCode:'',scanResult:null};
let app=document.querySelector('#app');let publishMarkup=()=>{};
const icon=(name)=>({home:'⌂',calendar:'▦',bus:'⇄',ticket:'▤',user:'◉',search:'⌕',arrow:'↗',pin:'⌖',clock:'◷',spark:'✳',back:'←'}[name]||'✳');
function brand(pro=false){return `<div class="brand"><span class="brand-mark">f</span>fodium${pro?'<span style="font-size:9px;letter-spacing:.08em;color:#7c8077;margin-left:2px">PRO</span>':''}</div>`}
function nav(active='Accueil'){return `<nav class="bottom-nav">${[['Accueil','⌂','home'],['Événements','▦','events'],['Transport','⇄','transport'],['Mes billets','▤','tickets'],['Profil','◉','profile']].map(([n,i,id])=>`<button class="${active===n?'active':''}" data-nav="${id}"><span class="nav-icon">${i}</span><span>${n==='Transport'?`Transport <span class="nav-soon">Bientôt</span>`:n}</span></button>`).join('')}</nav>`}
function header(){return `<header class="topbar">${brand()}<div class="nav-links"><button data-view="home">Découvrir</button><button data-nav="events">Événements</button><button data-teaser="true">Transport <span class="badge">Bientôt</span></button></div><div class="header-tools"><button class="quiet theme-toggle" data-theme-toggle title="Mode clair / sombre">${s.dark?'☼':'☾'}</button><select class="language-select" data-lang aria-label="Choisir la langue"><option value="fr" ${s.lang==='fr'?'selected':''}>FR</option><option value="en" ${s.lang==='en'?'selected':''}>EN</option><option value="wo" ${s.lang==='wo'?'selected':''}>WO</option></select><button class="quiet pro-link" data-teaser="true">Fodium Pro ↗</button><button class="dark-button" data-pro="true">Espace organisateur</button></div></header>`}
function card(e){return `<button class="event-card" data-event="${e.id}" aria-label="Découvrir ${e.name}"><div class="event-image" style="background-image:url('${e.img}')"><span class="event-date">${e.day}<br>${e.month}</span></div><div class="event-info"><span class="tag">${e.category}</span><h3>${e.name}</h3><div class="event-location">${icon('pin')} &nbsp;${e.city}</div><div class="event-price"><strong>${money(e.price)}</strong><span style="color:#777">Découvrir ↗</span></div></div></button>`}
function home(){const list=events.filter(discoveryMatches).sort((a,b)=>s.sort==="Date"?eventDate(a)-eventDate(b):s.sort==="Price"?a.price-b.price:0);return `<div class="wrap">${header()}<section class="hero"><div class="hero-copy"><div class="eyebrow">Vivez les choses en vrai</div><h1>Les moments<br>qui nous rassemblent.</h1><p>Concerts, festivals, découvertes. Votre prochain souvenir commence ici.</p><label class="searchbox"><span style="font-size:19px">⌕</span><input id="search" placeholder="Un événement, une ville…" value="${escapeHtml(s.query)}"><button class="lime-button" data-scroll="discover">Explorer</button></label></div></section><section class="shortcuts"><button class="shortcut" data-scroll="discover"><div class="shortcut-left"><span class="shortcut-icon">🎟</span><span><strong>Événements</strong><small>Trouvez votre prochain moment</small></span></div><span>↗</span></button><button class="shortcut" data-teaser="true"><div class="shortcut-left"><span class="shortcut-icon">🚌</span><span><strong>Transport</strong><small>On vous emmène bientôt</small></span></div><span class="badge">Bientôt</span></button></section><main class="discover" id="discover"><div class="section-head"><div><div class="eyebrow">À ne pas manquer</div><h2>Ça se passe près de vous.</h2></div><button class="quiet" data-nav="events" style="font-size:12px">Tout voir ↗</button></div><div class="filters">${['Tout','Festival','Musique','Culture','Gastronomie'].map(f=>`<button class="filter ${s.filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="events-grid">${list.map(card).join('')||'<p>Aucun événement pour cette recherche.</p>'}</div></main><footer class="footer"><span>${brand()}</span><span>Fait pour les moments qui comptent · © 2026</span><button class="quiet" data-pro="true">Vous organisez ? Fodium Pro ↗</button></footer></div>${nav(s.view==='tickets'?'Mes billets':'Accueil')}`}
function eventPage(){const e=events.find(x=>x.id===s.event)||events[0],total=e.price+(s.bundle?5000:0);return `<div class="wrap">${header()}<div class="page-head"><button class="back-link" data-view="home">← &nbsp;Retour aux événements</button></div><main class="detail-layout"><section><div class="detail-cover" style="background-image:url('${e.img}')"></div><div style="margin-top:19px"><span class="tag">${e.category}</span><h1 class="detail-title">${e.name}</h1><div class="detail-facts"><span>◷ &nbsp;${e.day} ${e.month} ${e.year} · 18:00</span><span>⌖ &nbsp;${e.city}</span><span>✳ &nbsp;Places limitées</span></div><p class="detail-description">${e.desc} Une expérience imaginée pour vous faire découvrir, rencontrer et partager. Réservez votre place en quelques secondes.</p><div class="pro-card" style="background:#f0f2eb"><div class="eyebrow">Le petit plus Fodium</div><p style="font:600 14px Manrope;margin:7px 0 4px">Votre soirée commence avant d’arriver.</p><span class="muted">Ajoutez une navette à votre billet et partez l’esprit tranquille.</span></div></div></section><aside class="purchase-card"><div class="eyebrow">Réservez votre place</div><h3>Choisissez votre formule</h3><p class="muted">Le bon plan pour profiter sans contraintes.</p><div class="option-row ${!s.bundle?'selected':''}" data-bundle="false"><span><b>Billet seul</b><small>Accès à l’événement</small></span><b>${money(e.price)}</b><span class="radio"></span></div><div class="option-row ${s.bundle?'selected':''}" data-bundle="true"><span><b>Billet + navette</b><small>Aller-retour inclus · +5 000 FCFA</small></span><span class="radio"></span></div>${s.bundle?`<div class="select-wrap"><label for="departure">Votre point de départ</label><select id="departure">${['Dakar — Liberté 6','Dakar — Plateau','Thiès — Gare routière','Saint-Louis — Place Faidherbe'].map(x=>`<option ${s.departure===x?'selected':''}>${x}</option>`).join('')}</select></div>`:''}<div style="margin-top:16px"><div class="price-line"><span>Billet</span><span>${money(e.price)}</span></div>${s.bundle?`<div class="price-line"><span>Navette · ${s.departure.split(' — ')[0]}</span><span>${money(5000)}</span></div>`:''}<div class="total-line"><span>Total</span><strong>${money(total)}</strong></div></div><button class="dark-button wide" data-checkout="true">Continuer · ${money(total)} &nbsp;→</button><p class="safe-note">Paiement simulé · Confirmation immédiate</p></aside></main></div>${nav()}`}
function modal(){if(!s.modal)return '';const e=events.find(x=>x.id===s.event)||events[0],sum=e.price+(s.bundle?5000:0);if(s.modal==='success')return `<div class="overlay"><div class="modal"><div class="success"><div class="success-icon">✓</div><div class="eyebrow">C’est dans la poche</div><h2>C'est confirmé !</h2><p>Votre billet pour <b>${e.name}</b> est prêt.<br>On a hâte de vous y retrouver.</p><div class="ticket-card"><span class="ticket-code">QR · FODIUM</span><small>${e.day} ${e.month} ${e.year} · ${e.city}</small><strong>${e.name}</strong><small>${s.bundle?`Billet + navette · ${s.departure}`:'Entrée générale · 1 personne'}</small></div><button class="dark-button wide" data-ticket="true">Voir mon billet ↗</button><button class="quiet" style="margin-top:12px" data-modal-close="true">Retour à l’accueil</button></div></div></div>`;return `<div class="overlay" data-overlay-close="true"><div class="modal" onclick="event.stopPropagation()"><div class="modal-top"><div><div class="eyebrow">Étape 02 · Paiement</div><h2>On y est presque.</h2><span class="muted">Choisissez comment régler, c’est tout.</span></div><button class="close" data-modal-close="true">×</button></div><div class="checkout-summary"><span><b style="font-size:12px">${e.name}</b><small style="display:block;color:#85877f;font-size:10px;margin-top:4px">${s.bundle?`Billet + navette · ${s.departure}`:'Billet seul · 1 personne'}</small></span><strong>${money(sum)}</strong></div><div class="eyebrow" style="margin-bottom:9px">Votre moyen de paiement</div>${[['Wave','W','Simple et rapide'],['Orange Money','OM','Paiement mobile sécurisé'],['Carte bancaire','▰','Visa, Mastercard']].map(([name,mark,sub])=>`<div class="payment-choice ${s.payment===name?'selected':''}" data-payment="${name}"><span class="payment-mark">${mark}</span><span style="flex:1"><strong>${name}</strong><small>${sub}</small></span><span class="radio"></span></div>`).join('')}<div class="modal-actions"><button class="back-link" data-modal-close="true">← Modifier ma formule</button><button class="dark-button" data-pay="true">Payer ${money(sum)} →</button></div></div></div>`}
function ticketPage(){return `<div class="wrap">${header()}<div class="page-head"><button class="back-link" data-view="home">← Retour</button><div class="eyebrow" style="margin-top:17px">Mes billets</div><h1 class="detail-title">Vos prochains moments.</h1></div><div class="pro-card" style="max-width:560px;margin:0 0 80px"><span class="tag">Confirmé</span><h2 style="font:700 20px Manrope;margin:15px 0 5px">${events.find(e=>e.id===s.event)?.name||'Walo Festival'}</h2><p class="muted">27 décembre 2026 · 18:00 · Dagana</p><div class="ticket-card"><span class="ticket-code">QR · FODIUM</span><small>27 DÉC 2026 · DAGANA</small><strong>${events.find(e=>e.id===s.event)?.name||'Walo Festival'}</strong><small>${s.bundle?`Billet + navette · ${s.departure}`:'Entrée générale · 1 personne'}</small></div><button class="pill-button" data-view="home">Découvrir d’autres événements</button></div></div>${nav('Mes billets')}`}
function proTop(){return `<header class="pro-top">${brand(true)}<div class="header-tools"><button class="quiet" data-view="home" style="font-size:11px">← Fodium public</button><button class="quiet theme-toggle" data-theme-toggle title="Mode clair / sombre">${s.dark?"☼":"☾"}</button><select class="language-select" data-lang aria-label="Choisir la langue"><option value="fr" ${s.lang==="fr"?"selected":""}>FR</option><option value="en" ${s.lang==="en"?"selected":""}>EN</option><option value="wo" ${s.lang==="wo"?"selected":""}>WO</option></select><div class="avatar">AD</div></div></header>`}
function proNav(){return `<div class="pro-nav">${[['home','Accueil'],['events','Événements'],['dashboard','Tableau de bord']].map(([id,n])=>`<button data-propage="${id}" class="${s.proPage===id?'active':''}">${n}</button>`).join('')}</div>`}
function proBottom(){return `<nav class="pro-bottom"><button data-propage="home"><span class="nav-icon">⌂</span>Accueil</button><button data-propage="events"><span class="nav-icon">▦</span>Événements</button><button data-actions="true" class="plus">＋</button><button data-propage="dashboard"><span class="nav-icon">▥</span>Activité</button><button data-propage="profile"><span class="nav-icon">◉</span>Profil</button></nav>`}
function proWelcome(){return `<div class="pro-shell">${proTop()}<main class="teaser-pro"><div class="eyebrow">Un même écosystème, deux façons d’avancer</div><h1 class="display" style="font-size:clamp(32px,5vw,47px);margin:13px 0 7px">Bienvenue chez Fodium.</h1><p class="muted">Qu’est-ce qu’on fait ensemble aujourd’hui ?</p><div class="universe-grid"><button class="universe active" data-prologin="true"><span style="font-size:20px">◈</span><h2>Événement <span style="float:right;font-size:17px">↗</span></h2><p>Billetterie · Gestion · Équipes<br>Partenaires · Contrôle</p><span class="lime-button" style="display:inline-block;margin-top:12px;padding:10px 14px">Continuer</span></button><button class="universe" data-teaser="true"><span style="font-size:20px">⇄</span><h2>Transport <span class="badge">Bientôt</span></h2><p>Vos navettes et trajets<br>interurbains, au même endroit.</p></button></div><div style="font-size:10px;color:#92958d;margin-top:23px">Vous organisez ? Simplifiez la préparation, la vente et le pilotage de vos événements.</div></main></div>`}
function proLogin(){return `<div class="pro-shell">${proTop()}<main class="auth-wrap"><section class="auth-card"><button class="back-link" data-propage="welcome">← Retour</button><div class="eyebrow" style="margin-top:18px">Fodium Pro · Espace organisateur</div><h1>Ravi de vous revoir.</h1><p>Connectez-vous pour retrouver votre activité et vos événements.</p><div class="field"><label>E-mail ou téléphone</label><input id="login-id" placeholder="vous@exemple.com ou +221…"></div><div class="field"><div style="display:flex;justify-content:space-between"><label>Mot de passe</label><button class="quiet" data-forgot="true" style="font-size:10px">Oublié ?</button></div><input id="login-pass" type="password" placeholder="Votre mot de passe"></div><button class="dark-button wide" style="margin-top:18px" data-login="true">Se connecter →</button><div class="auth-alt">ou</div><button class="google-button" data-login="true"><b style="font-size:14px;margin-right:8px">G</b> Continuer avec Google</button><div style="text-align:center;border-top:1px solid #eee;margin-top:20px;padding-top:16px"><button class="quiet" data-pin="true" style="font-size:11px">⌑ &nbsp;Déverrouiller avec mon PIN à 4 chiffres</button><div style="font-size:9px;color:#9a9c95;margin-top:6px">Pour un appareil déjà authentifié</div></div></section></main></div>`}
function eventRows(){return events.slice(0,3).map((e,i)=>`<div class="event-row"><div class="event-thumb" style="background-image:url('${e.img}')"></div><div class="event-row-main"><strong>${i===0?'WALO UP 2026':e.name}</strong><small>${e.day} ${e.month} 2026 · ${i===0?'Dagana':e.city}</small><div class="progress"><span style="width:${[67,48,32][i]}%"></span></div></div><div class="event-row-metric"><b>${[742,386,215][i]} billets</b><span class="muted">${money([1860000,940000,525000][i])}</span></div><button class="quiet" data-propage="event" aria-label="Gérer ${e.name}">↗</button></div>`).join('')}
function proHome(){return `<div class="pro-shell">${proTop()}<main class="pro-frame">${proNav()}<div class="pro-greeting"><div><div class="eyebrow">JEUDI 15 OCTOBRE 2026</div><h1>Bonjour, Aïssatou.</h1><p>Voici ce qui se passe dans votre activité.</p></div><div class="avatar">AD</div></div><div class="pro-grid"><div><section class="pro-card upcoming"><div class="upcoming-content"><div class="eyebrow">Votre prochain événement · Dans 73 jours</div><h2>WALO UP 2026</h2><p>27 décembre 2026 &nbsp;·&nbsp; Dagana</p><div class="upcoming-stats"><span><strong>742</strong><small>billets vendus</small></span><span><strong>1,86 M</strong><small>FCFA générés</small></span><span><strong>+18%</strong><small>cette semaine</small></span></div><button class="lime-button" data-propage="event">Gérer l’événement ↗</button></div></section><section class="pro-card activity-card"><div class="pro-section-head"><h2>Vos événements</h2><button class="quiet" data-propage="events" style="font-size:10px">Tout voir ↗</button></div>${eventRows()}</section><section class="pro-card activity-card"><div class="pro-section-head"><h2>Raccourcis</h2><span class="muted">Les actions utiles, à portée de main</span></div><div class="quick-row"><button data-action="Créer un événement">＋ Créer un événement</button><button data-action="Demander des billets physiques">▤ Billets physiques</button><button data-action="Ajouter un vendeur">＋ Ajouter un vendeur</button></div></section></div><div><section class="pro-card"><div class="pro-section-head"><h2>Dernières ventes</h2><span class="muted">Aujourd’hui</span></div><div class="sale-list">${[['FN','Fatou Ndiaye','Billet standard · 14:32','30 000'],['MD','Moussa Diop','Billet + navette · 13:58','35 000'],['AS','Aminata Sarr','Billet standard · 12:41','30 000'],['IB','Ibrahima Ba','Billet standard · 11:17','30 000']].map(([i,n,d,p])=>`<div class="sale"><div class="sale-person"><span class="sale-avatar">${i}</span><span><b>${n}</b><small>${d}</small></span></div><strong>${p} F</strong></div>`).join('')}</div></section><section class="pro-card activity-card"><div class="pro-section-head"><h2>À suivre</h2><span class="badge">1 alerte</span></div><div class="alert"><b>Billets physiques</b><br>Votre dernière demande de 200 billets est prête à être confirmée.</div><div class="alert" style="background:#f8f4eb;color:#62573f"><b style="color:#6a5425">Complétez votre profil</b><br>Ajoutez vos coordonnées de paiement pour accélérer vos retraits.</div></section><section class="pro-card activity-card"><div class="eyebrow">Votre activité avance</div><p style="font:600 15px Manrope;line-height:1.55">+18 % de ventes cette semaine.<br>Continuez comme ça.</p><button class="pill-button" data-propage="dashboard">Voir les performances ↗</button></section></div></div></main>${proBottom()}</div>`}
function proEvents(){return `<div class="pro-shell">${proTop()}<main class="pro-frame">${proNav()}<div class="pro-greeting"><div><div class="eyebrow">VOTRE PROGRAMMATION</div><h1>Vos événements.</h1><p>Le détail de vos projets, du lancement au dernier billet.</p></div><button class="dark-button" data-action="Créer un événement">＋ Créer</button></div><section class="pro-card"><div class="pro-section-head"><h2>Tous les événements <span class="muted">· 3</span></h2><span class="badge">2026</span></div>${eventRows()}</section><div class="pro-card activity-card"><div class="eyebrow">Un espace qui grandira avec vous</div><p class="muted" style="line-height:1.7">Billetterie, finances, dépenses, équipe, vendeurs, contrôle d’accès, partenaires, stands et rapports : vos outils s’organisent autour de chaque événement.</p><div class="quick-row">${['Billetterie','Finances','Équipe','Partenaires','Contrôle','Rapports'].map(x=>`<span class="tag">${x} · bientôt</span>`).join('')}</div></div></main>${proBottom()}</div>`}
function dashboard(){return `<div class="pro-shell">${proTop()}<main class="pro-frame">${proNav()}<div class="pro-greeting"><div><div class="eyebrow">VUE D’ENSEMBLE · 2026</div><h1>Votre activité en chiffres.</h1><p>Comprendre la tendance pour décider de la suite.</p></div><span class="badge">Cette année</span></div><div class="stat-grid">${[['Chiffre d’affaires','3 325 000 F','+18,4 % vs mois dernier'],['Billets vendus','1 343','+12,8 % vs mois dernier'],['Taux de remplissage','68 %','+6 pts vs mois dernier'],['Scans réalisés','624','46 % des billets émis'],['Vendeurs actifs','12','sur 15 invités'],['Événements actifs','3','1 à venir prochainement']].map(([k,v,c])=>`<div class="stat-card"><small>${k}</small><strong>${v}</strong><span>↗ ${c}</span></div>`).join('')}</div><section class="pro-card activity-card"><div class="pro-section-head"><div><h2>La billetterie progresse.</h2><span class="muted">Ventes par semaine · Walo Up 2026</span></div><span class="badge">7 semaines</span></div><div class="chart">${[['01 oct',30],['08 oct',45],['15 oct',38],['22 oct',57],['29 oct',49],['05 nov',75],['12 nov',63],['19 nov',92]].map(([d,h],i)=>`<div class="bar-group"><div class="bar ${i===7?'hot':''}" style="height:${h}%"></div><span class="bar-label">${d}</span></div>`).join('')}</div></section><section class="pro-card activity-card"><div class="pro-section-head"><h2>Résultats par événement</h2><span class="muted">Revenus bruts</span></div>${eventRows()}</section></main>${proBottom()}</div>`}
function proEvent(){return `<div class="pro-shell">${proTop()}<main class="pro-frame">${proNav()}<button class="back-link" data-propage="events">← Tous les événements</button><div class="pro-grid" style="margin-top:15px"><div><section class="pro-card upcoming"><div class="upcoming-content"><div class="eyebrow">EN VENTE · PLUS QUE 73 JOURS</div><h2>WALO UP 2026</h2><p>27 décembre 2026 · Dagana</p><div class="upcoming-stats"><span><strong>742</strong><small>billets vendus</small></span><span><strong>1,86 M</strong><small>FCFA générés</small></span></div></div></section><section class="pro-card activity-card"><div class="pro-section-head"><h2>Progression des ventes</h2><span class="badge">Objectif · 1 100 billets</span></div><div class="progress" style="height:9px"><span style="width:67%"></span></div><p class="muted" style="margin-top:11px">67 % de l’objectif atteint · 358 billets restants</p></section></div><section class="pro-card"><div class="eyebrow">GESTION DE L’ÉVÉNEMENT</div><h2 style="font:700 19px Manrope;margin:8px 0 3px">Tout est au même endroit.</h2><p class="muted">Les outils de votre événement, prêts à grandir.</p>${['Vue d’ensemble','Billetterie','Finances & dépenses','Équipe & accès','Vendeurs','Agents de contrôle','Partenaires & sponsors','Stands & restauration','Documents & rapports'].map((x,i)=>`<button class="shortcut" style="width:100%;padding:12px;margin-top:7px"><span style="font-size:11px;font-weight:600">${['◫','▤','◷','♙','↗','⌗','◇','⌂','▧'][i]} &nbsp; ${x}</span><span class="badge">Bientôt</span></button>`).join('')}</section></div></main>${proBottom()}</div>`}
function pinModal(){return `<div class="overlay"><div class="modal" style="max-width:360px;text-align:center"><button class="close" data-modal-close="true" style="float:right">×</button><div class="eyebrow" style="margin-top:16px">Appareil reconnu</div><h2>Votre code PIN</h2><p class="muted">Saisissez votre code à 4 chiffres pour reprendre.</p><div style="display:flex;gap:10px;justify-content:center;margin:22px 0">${[1,2,3,4].map((_,i)=>`<input class="pin-digit" maxlength="1" inputmode="numeric" style="width:48px;height:54px;text-align:center;border:1px solid #dedfd8;border-radius:12px;font-size:23px" aria-label="Chiffre ${i+1}">`).join('')}</div><button class="dark-button wide" data-login="true">Déverrouiller</button><button class="quiet" style="margin-top:13px;font-size:10px" data-modal-close="true">Utiliser mon mot de passe</button></div></div>`}
function actionSheet(){return `<div class="quick-sheet" data-sheet-close="true"><section class="sheet" onclick="event.stopPropagation()"><div class="sheet-handle"></div><div style="display:flex;justify-content:space-between;align-items:start"><div><div class="eyebrow">Raccourcis organisateur</div><h2 style="font:700 22px Manrope;letter-spacing:-.8px;margin:5px 0">On s’occupe de quoi ?</h2><span class="muted">Tout ce dont vous avez besoin pour avancer.</span></div><button class="close" data-sheet-close="true">×</button></div><div class="action-grid">${[['＋','Créer un événement','Lancer votre prochain projet'],['▤','Demander des billets physiques','Préparer vos billets imprimés'],['♙','Ajouter un vendeur','Inviter votre équipe commerciale'],['⌗','Ajouter un agent de contrôle','Organiser les accès'],['◇','Ajouter un partenaire','Sponsor, exposant ou média']].map(([i,n,d])=>`<button class="action-tile" data-action="${n}"><span class="action-icon">${i}</span><strong>${n}</strong><small>${d}</small></button>`).join('')}</div></section></div>`}
function eventCreator(){const d=s.draft;return `<div class="pro-shell">${proTop()}<main class="pro-frame"><button class="back-link" data-propage="home">← Retour au pilotage</button><div class="creator-heading"><div><div class="eyebrow">CRÉATEUR FODIUM · ÉTAPE ${s.wizardStep} SUR 3</div><h1>Donnez vie à votre prochain événement.</h1><p class="muted">Quelques détails pour préparer votre page de vente.</p></div><span class="step-count">0${s.wizardStep} / 03</span></div><div class="wizard-progress"><span style="width:${s.wizardStep*33.333}%"></span></div><div class="creator-layout"><section class="pro-card creator-form">${s.wizardStep===1?`<div class="eyebrow">01 · IDENTITÉ</div><h2>De quoi s’agit-il ?</h2><label>Nom de l’événement<input data-draft="name" value="${escapeHtml(d.name)}" placeholder="Ex. Dakar Open Air"></label><div class="form-row"><label>Catégorie<select data-draft="category">${['Festival','Musique','Culture','Gastronomie'].map(x=>`<option ${d.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Ville<input data-draft="city" value="${escapeHtml(d.city)}" placeholder="Dakar"></label></div>`:s.wizardStep===2?`<div class="eyebrow">02 · PRATIQUE</div><h2>Les détails utiles.</h2><div class="form-row"><label>Date<input data-draft="date" type="date" value="${d.date}"></label><label>Capacité<input data-draft="capacity" type="number" min="1" value="${d.capacity}"></label></div><label>Prix du billet<input data-draft="price" type="number" min="0" step="500" value="${d.price}"> <small>FCFA</small></label><p class="form-note">Vous pourrez ajouter plusieurs tarifs et la navette ensuite.</p>`:`<div class="eyebrow">03 · PRÊT À PUBLIER</div><h2>Relisez votre événement.</h2><p>Votre page de vente sera publiée en mode démonstration.</p><div class="creator-summary"><b>${escapeHtml(d.name||'Votre événement')}</b><span>${escapeHtml(d.category)} · ${escapeHtml(d.city)}</span><span>${d.date} · ${money(Number(d.price)||0)} · ${d.capacity} places</span></div>`}<div class="wizard-actions">${s.wizardStep>1?'<button class="pill-button" data-wizard="back">← Précédent</button>':'<span></span>'}${s.wizardStep<3?'<button class="dark-button" data-wizard="next">Continuer →</button>':'<button class="lime-button" data-wizard="publish">Publier mon événement ↗</button>'}</div></section><aside class="creator-preview"><div class="preview-label">APERÇU DE VOTRE PAGE PUBLIQUE <span class="badge">EN DIRECT</span></div><div class="preview-cover" style="background-image:url('${events.find(e=>e.category===d.category)?.img||events[0].img}')"></div><div class="preview-copy"><span class="tag">${escapeHtml(d.category)}</span><h2>${escapeHtml(d.name||'Le nom de votre événement')}</h2><p>⌖ ${escapeHtml(d.city||'Votre ville')} · ◷ ${d.date||'Choisissez une date'}</p><div class="total-line"><span>À partir de</span><strong>${money(Number(d.price)||0)}</strong></div><button class="dark-button wide" disabled>Réserver mon billet</button></div></aside></div></main>${proBottom()}</div>`}
function proAttendees(){const list=attendees.filter(a=>(s.attendeeFilter==='Tous'||a.status===s.attendeeFilter)&&`${a.name} ${a.email} ${a.event} ${a.id}`.toLowerCase().includes(s.attendeeSearch.toLowerCase()));return `<div class="pro-shell">${proTop()}<main class="pro-frame">${proNav()}<div class="creator-heading"><div><div class="eyebrow">WALO UP 2026 · GESTION</div><h1>Vos participants.</h1><p class="muted">Retrouvez les acheteurs et le statut de leurs billets.</p></div><button class="dark-button" data-export-csv>↓ Exporter CSV</button></div><div class="stat-grid attendee-stats"><div class="stat-card"><small>Participants</small><strong>1 343</strong><span>sur tous les événements</span></div><div class="stat-card"><small>Billets scannés</small><strong>624</strong><span>46 % des billets émis</span></div><div class="stat-card"><small>Navette incluse</small><strong>218</strong><span>départs à confirmer</span></div></div><section class="pro-card attendee-panel"><div class="attendee-controls"><input data-attendee-search value="${escapeHtml(s.attendeeSearch)}" placeholder="Rechercher un nom, e-mail ou billet…"><select data-attendee-filter>${['Tous','Valide','Scanné'].map(x=>`<option ${s.attendeeFilter===x?'selected':''}>${x}</option>`).join('')}</select><span class="badge">${list.length} résultats</span></div><div class="attendee-table"><div class="attendee-row table-head"><span>PARTICIPANT</span><span>ÉVÉNEMENT</span><span>BILLET</span><span>MONTANT</span><span>STATUT</span></div>${list.map(a=>`<div class="attendee-row"><span><b>${a.name}</b><small>${a.email}</small></span><span>${a.event}</span><span class="mono">${a.id}</span><b>${money(a.amount)}</b><span class="status-pill ${a.status==='Scanné'?'scanned':''}">${a.status}</span></div>`).join('')||'<p class="muted">Aucun participant ne correspond à votre recherche.</p>'}</div></section></main>${proBottom()}</div>`}
function proCheckin(){const result=s.scanResult;return `<div class="pro-shell">${proTop()}<main class="pro-frame">${proNav()}<div class="creator-heading"><div><div class="eyebrow">WALO UP 2026 · CONTRÔLE D’ACCÈS</div><h1>Une entrée fluide, enfin.</h1><p class="muted">Simulez un scan QR pour valider l’arrivée des participants.</p></div><span class="badge live-badge">● CONTRÔLE ACTIF</span></div><div class="checkin-layout"><section class="scanner-panel"><div class="scan-frame"><div class="scan-corners"></div><span class="scan-code">⌗</span><div class="scan-line"></div></div><p>Placez le QR du billet dans la zone<br><small>ou saisissez son code pour la démo</small></p><form id="scan-form"><input id="scan-input" value="${escapeHtml(s.scanCode)}" placeholder="FD-WALO-001"><button class="lime-button">Vérifier le billet →</button></form><div class="scan-examples"><button class="pill-button" data-scan-sample="FD-WALO-001">Billet valide</button><button class="pill-button" data-scan-sample="FD-WALO-003">Déjà scanné</button><button class="pill-button" data-scan-sample="FD-XXXX-999">Inconnu</button></div></section><section class="scan-result ${result?.valid?'valid':result?'invalid':''}">${result?`<div class="scan-result-icon">${result.valid?'✓':'!'}</div><div class="eyebrow">${result.valid?'ACCÈS AUTORISÉ':result.used?'BILLET DÉJÀ UTILISÉ':'BILLET NON RECONNU'}</div><h2>${result.name||'Billet introuvable'}</h2><p>${result.valid?`${result.event} · ${result.type}`:result.used?'Ce billet a déjà été scanné à 19:42.':'Vérifiez le code ou contactez l’équipe d’accueil.'}</p><span class="status-pill ${result.valid?'':'scanned'}">${result.valid?'Entrée validée':result.used?'Déjà utilisé':'Code invalide'}</span>`:`<span class="result-placeholder">⌗</span><h2>Prêt pour le prochain scan.</h2><p>Le résultat apparaît ici en moins d’une seconde.</p>`}</section></div><section class="pro-card recent-checkins"><div class="pro-section-head"><h2>Derniers contrôles</h2><span class="muted">Aujourd’hui</span></div>${attendees.filter(a=>a.status==='Scanné').map(a=>`<div class="event-row"><span class="sale-avatar">✓</span><div class="event-row-main"><b>${a.name}</b><small>${a.event} · Porte principale</small></div><span class="status-pill scanned">Scanné · 19:42</span></div>`).join('')}</section></main>${proBottom()}</div>`}
function proInsights(){return `<div class="pro-shell">${proTop()}<main class="pro-frame">${proNav()}<div class="creator-heading"><div><div class="eyebrow">FODIUM INSIGHTS</div><h1>Les chiffres, et la suite.</h1><p class="muted">Des signaux simples pour décider quoi faire après.</p></div><span class="badge">Données de démo</span></div><div class="insight-grid"><article class="insight-card"><span>✦</span><div class="eyebrow">CATÉGORIE EN HAUSSE</div><h2>Les festivals attirent 34 % de plus.</h2><p>Sur les 30 derniers jours, les événements Festival progressent plus vite que les autres catégories.</p><button class="quiet" data-propage="dashboard">Voir la tendance ↗</button></article><article class="insight-card"><span>◷</span><div class="eyebrow">BON MOMENT POUR PUBLIER</div><h2>Jeudi, entre 18 h et 20 h.</h2><p>Vos ventes accélèrent après vos publications du jeudi soir.</p><button class="quiet" data-propage="attendees">Voir les participants ↗</button></article><article class="insight-card"><span>⇄</span><div class="eyebrow">OPPORTUNITÉ NAVETTE</div><h2>1 acheteur sur 3 choisit le pass transport.</h2><p>Les départs depuis Dakar — Liberté 6 sont les plus demandés.</p><button class="quiet" data-propage="checkin">Préparer le contrôle ↗</button></article></div><section class="pro-card activity-card"><div class="pro-section-head"><h2>Catégories qui mobilisent</h2><span class="muted">Billets vendus · simulation</span></div>${[['Festival',742,73],['Musique',386,48],['Culture',215,31]].map(([n,v,p])=>`<div class="category-progress"><span>${n}</span><div class="progress"><span style="width:${p}%"></span></div><b>${v}</b></div>`).join('')}</section></main>${proBottom()}</div>`}
function localizeMarkup(markup){const doc=new DOMParser().parseFromString(markup,'text/html');const d=translations[s.lang]||{};const walker=doc.createTreeWalker(doc.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const key=node.nodeValue.trim();if(d[key])node.nodeValue=node.nodeValue.replace(key,d[key])}const input=doc.querySelector('#search');if(input)input.placeholder=s.lang==='en'?'An event, a city…':s.lang==='wo'?'Wàll, dëkk…':'Un événement, une ville…';document.documentElement.lang=s.lang==='wo'?'wo':s.lang;return doc.body.innerHTML}
function assistantWidget(){const title=s.lang==='en'?'Fodium assistant':s.lang==='wo'?'Ndimbal Fodium':'Assistant Fodium';const welcome=s.lang==='en'?'Hi! I can help you find an event, understand the shuttle pass or prepare a booking.':s.lang==='wo'?'Salaam! Maa ngi lay dimbali ci wàll yi, navette bi ak jënd billet.':'Bonjour ! Je peux vous aider à trouver un événement, choisir une navette ou préparer une réservation.';return `<div class="assistant-wrap"><section class="assistant-panel ${s.chatOpen?'open':''}" aria-hidden="${!s.chatOpen}"><header class="assistant-head"><span class="assistant-avatar">✦</span><span style="flex:1"><b>${title}</b><small>${s.lang==='en'?'Here to help':s.lang==='wo'?'Maa ngi fi':'À votre écoute'}</small></span><button data-chat-close aria-label="Fermer">×</button></header><div class="assistant-messages" id="chat-messages">${s.chatMessages.length?s.chatMessages.map(m=>`<div class="chat-bubble ${m.from}">${escapeHtml(m.text)}</div>`).join(''):`<div class="chat-bubble bot">${welcome}</div>`}<div class="chat-suggestions">${(s.lang==='en'?['Upcoming events','How does the shuttle work?','Help me book']:s.lang==='wo'?['Wàll yi','Navette bi naka la?','Dimbal ma jënd']:['Les événements','Comment marche la navette ?','Aidez-moi à réserver']).map(q=>`<button data-chat-suggest="${q}">${q}</button>`).join('')}</div></div><form class="assistant-compose" id="chat-form"><input id="chat-input" placeholder="${s.lang==='en'?'Write a message…':s.lang==='wo'?'Bind fii…':'Écrivez votre message…'}" autocomplete="off"><button aria-label="Envoyer">↑</button></form><div class="assistant-disclaimer">${s.lang==='en'?'Demo assistant · no personal data needed':s.lang==='wo'?'Ndimbal demo · du laaj say xibaar':'Assistant démo · aucune donnée personnelle'}</div></section><button class="assistant-launch ${s.chatOpen?'hidden':''}" data-chat-open aria-label="Ouvrir l’assistant"><span>✦</span><b>${s.lang==='en'?'Need help?':s.lang==='wo'?'Ndimbal?':'Besoin d’aide ?'}</b></button></div>`}
function render(){let out;if(s.view==='home')out=augmentPublic(home());else if(s.view==='event')out=augmentPublic(eventPage());else if(s.view==='tickets')out=s.ticketTab==='Calendrier'?calendarPage():ticketHub();else if(s.view==='pro'){out=s.proPage==='welcome'?proWelcome():s.proPage==='login'?proLogin():s.proPage==='events'?proEvents():s.proPage==='dashboard'?dashboard():s.proPage==='event'?proEvent():s.proPage==='create'?eventCreator():s.proPage==='attendees'?proAttendees():s.proPage==='checkin'?proCheckin():s.proPage==='insights'?proInsights():proHome();out=proEnhancements(out)}else out=home();document.body.classList.toggle('dark-mode',s.dark);publishMarkup(localizeMarkup(out+(s.modal==='pin'?pinModal():modal())+(s.modal==='actions'?actionSheet():'')+assistantWidget()))}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function bind(){document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{s.event=b.dataset.event;s.view='event';s.bundle=false;window.scrollTo(0,0);render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{s.view=b.dataset.view;s.modal='';render();window.scrollTo(0,0)});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{const id=b.dataset.nav;if(id==='events'){s.view='home';s.filter='Tout';render();document.querySelector('#discover')?.scrollIntoView({behavior:'smooth'})}else if(id==='tickets'){s.view='tickets';render()}else if(id==='home'){s.view='home';render();window.scrollTo({top:0,behavior:'smooth'})}else if(id==='transport')toast('Fodium Transport arrive bientôt. On vous prévient ?');else toast('Votre profil Fodium arrive bientôt.')});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{s.filter=b.dataset.filter;render()});document.querySelectorAll('[data-scroll]').forEach(b=>b.onclick=()=>document.querySelector('#'+b.dataset.scroll)?.scrollIntoView({behavior:'smooth'}));document.querySelectorAll('[data-bundle]').forEach(b=>b.onclick=()=>{s.bundle=b.dataset.bundle==='true';render()});document.querySelector('#departure')&&(document.querySelector('#departure').onchange=e=>{s.departure=e.target.value;render()});document.querySelector('#search')&&(document.querySelector('#search').oninput=e=>{const pos=e.target.selectionStart;s.query=e.target.value;const y=window.scrollY;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos);window.scrollTo(0,y)});document.querySelectorAll('[data-checkout]').forEach(b=>b.onclick=()=>{s.modal='checkout';render()});document.querySelectorAll('[data-payment]').forEach(b=>b.onclick=()=>{s.payment=b.dataset.payment;render()});document.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=()=>{s.modal='';render()});document.querySelectorAll('[data-overlay-close]').forEach(b=>b.onclick=()=>{s.modal='';render()});document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>{b.textContent='Paiement en cours…';b.disabled=true;setTimeout(()=>{if(!s.purchases.includes(s.event)){s.purchases.unshift(s.event);localStorage.setItem('fodium-purchases',JSON.stringify(s.purchases))}s.modal='success';render()},1000)});document.querySelectorAll('[data-ticket]').forEach(b=>b.onclick=()=>{s.modal='';s.view='tickets';s.ticket=true;render()});document.querySelectorAll('[data-pro]').forEach(b=>b.onclick=()=>{s.view='pro';s.proPage='welcome';render();window.scrollTo(0,0)});document.querySelectorAll('[data-prologin]').forEach(b=>b.onclick=()=>{s.proPage='login';render()});document.querySelectorAll('[data-propage]').forEach(b=>b.onclick=()=>{s.view='pro';s.proPage=b.dataset.propage;render();window.scrollTo(0,0)});document.querySelectorAll('[data-login]').forEach(b=>b.onclick=()=>{s.modal='';s.view='pro';s.proPage='home';render();toast('Bienvenue dans votre espace Fodium Pro.')});document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>{s.modal='pin';render();document.querySelector('.pin-digit')?.focus()});document.querySelectorAll('.pin-digit').forEach((input,i,all)=>input.oninput=()=>{input.value=input.value.replace(/\D/g,'').slice(0,1);if(input.value&&all[i+1])all[i+1].focus();if([...all].every(x=>x.value))toast('PIN accepté · Bienvenue !')});document.querySelectorAll('[data-actions]').forEach(b=>b.onclick=()=>{s.modal='actions';render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{s.modal='';render();toast(`${b.dataset.action} · Cette action arrive bientôt.`)});document.querySelectorAll('[data-teaser]').forEach(b=>b.onclick=()=>toast('Fodium Transport arrive bientôt. Restez dans le coin !'));document.querySelectorAll('[data-forgot]').forEach(b=>b.onclick=()=>toast('Un lien de réinitialisation sera envoyé à votre adresse.'))}
function bindAssistant(){document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.onclick=()=>{s.dark=!s.dark;localStorage.setItem('fodium-dark',s.dark);render()});document.querySelectorAll('[data-lang]').forEach(el=>el.onchange=()=>{s.lang=el.value;localStorage.setItem('fodium-lang',s.lang);render()});document.querySelectorAll('[data-chat-open]').forEach(b=>b.onclick=()=>{s.chatOpen=true;render()});document.querySelectorAll('[data-chat-close]').forEach(b=>b.onclick=()=>{s.chatOpen=false;render()});document.querySelectorAll('[data-chat-suggest]').forEach(b=>b.onclick=()=>sendChat(b.dataset.chatSuggest));document.querySelector('#chat-form')&&(document.querySelector('#chat-form').onsubmit=e=>{e.preventDefault();const input=document.querySelector('#chat-input');if(input.value.trim())sendChat(input.value.trim())});document.querySelectorAll('.sheet[data-sheet-close]').forEach(el=>el.onclick=e=>{if(e.target===el){s.modal='';render()}})}
function sendChat(message){const q=message.toLowerCase();let reply;if(/navette|transport|bus|trajet|shuttle/.test(q))reply=s.lang==='en'?'The shuttle pass adds 5,000 FCFA to your ticket. Choose a departure point on the event page; the round trip is included.':s.lang==='wo'?'Navette bi dafay yokk 5 000 FCFA ci billet bi. Tànnal fu ngay jóge ci xët wàll bi.':'La navette ajoute 5 000 FCFA au billet. Choisissez votre point de départ sur la fiche événement ; l’aller-retour est inclus.';else if(/payer|paiement|réserv|book|ticket|billet|jënd/.test(q))reply=s.lang==='en'?'Open an event, choose a ticket or ticket + shuttle, then select Wave, Orange Money or card. This demo simulates the payment.':s.lang==='wo'?'Ubbil wàll, tànnal billet walla billet ak navette, dale ko tànn Wave, Orange Money walla carte.':'Ouvrez un événement, choisissez billet seul ou billet + navette, puis Wave, Orange Money ou carte. Le paiement est simulé dans cette démo.';else if(/organis|pro|vendeur|organizer/.test(q))reply=s.lang==='en'?'For your organizer space, use “Organizer space” in the top bar. You can see upcoming events, sales and activity.':s.lang==='wo'?'Ngir sa espace organisateur, jëfandikool “Espace organisateur” ci kaw.':'Pour accéder à votre espace organisateur, utilisez « Espace organisateur » dans la barre du haut.';else reply=s.lang==='en'?`Here are a few upcoming events: ${events.slice(0,3).map(e=>`${e.name} (${money(e.price)})`).join(' · ')}. Open one to see details.`:s.lang==='wo'?`Wàll yi: ${events.slice(0,3).map(e=>`${e.name} (${money(e.price)})`).join(' · ')}. Tàppal benn ngir gis leeral.`:`Voici quelques événements à venir : ${events.slice(0,3).map(e=>`${e.name} (${money(e.price)})`).join(' · ')}. Ouvrez une fiche pour les détails.`;s.chatMessages.push({from:'user',text:message},{from:'bot',text:reply});s.chatOpen=true;render();const box=document.querySelector('#chat-messages');if(box)box.scrollTop=box.scrollHeight}
const translations={en:{'Découvrir':'Discover','Événements':'Events','Bientôt':'Coming soon','Espace organisateur':'Organizer space','Vivez les choses en vrai':'Experience it for real','Les moments':'The moments','qui nous rassemblent.':'that bring us together.','Concerts, festivals, découvertes. Votre prochain souvenir commence ici.':'Concerts, festivals, discoveries. Your next memory starts here.','Explorer':'Explore','Trouvez votre prochain moment':'Find your next moment','On vous emmène bientôt':'Your ride is coming soon','À ne pas manquer':'Worth discovering','Ça se passe près de vous.':'Happening near you.','Tout voir ↗':'See all ↗','Réservez votre place':'Book your place','Choisissez votre formule':'Choose your ticket','Billet seul':'Ticket only','Accès à l’événement':'Event entry','Billet + navette':'Ticket + shuttle','Votre point de départ':'Your departure point','Total':'Total','Continuer':'Continue','Paiement simulé · Confirmation immédiate':'Demo payment · Instant confirmation','Vos événements':'Your events','Bonjour, Aïssatou.':'Hello, Aïssatou.','Voici ce qui se passe dans votre activité.':'Here’s what’s happening in your business.','Dernières ventes':'Recent sales','Raccourcis':'Quick actions','Tableau de bord':'Dashboard','Créer un événement':'Create an event'},wo:{'Découvrir':'Xoolal','Événements':'Wàll yi','Bientôt':'Dina ñëw','Espace organisateur':'Espace doxal','À ne pas manquer':'Bul ñàkk','Ça se passe près de vous.':'Li ci sa wetu','Explorer':'Xoolal','Total':'Mbooleem'}};
export function startFodium(updateMarkup){publishMarkup=updateMarkup;app=document.querySelector('#app');render()}
function shareInvite(eventId){const code=`FOD-${eventId.toUpperCase()}-${Math.random().toString(36).slice(2,7).toUpperCase()}`;const link=`https://fodium.app/join/${code}`;navigator.clipboard?.writeText(link).catch(()=>{});toast(`Lien de groupe copié : ${link}`)}
function exportCalendar(){const selected=events.filter(e=>s.purchases.includes(e.id));const body=selected.map(e=>`BEGIN:VEVENT\nSUMMARY:${e.name}\nDTSTART:${eventDate(e).toISOString().replace(/[-:]/g,'').slice(0,15)}Z\nLOCATION:${e.city}\nEND:VEVENT`).join('\n');const blob=new Blob([`BEGIN:VCALENDAR\nVERSION:2.0\n${body}\nEND:VCALENDAR`],{type:'text/calendar'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fodium-evenements.ics';a.click();URL.revokeObjectURL(a.href)}
function exportParticipants(){const rows=[['Code billet','Nom','E-mail','Événement','Type','Montant FCFA','Statut'],...attendees.map(a=>[a.id,a.name,a.email,a.event,a.type,a.amount,a.status])];const csv=rows.map(row=>row.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='fodium-participants.csv';a.click();URL.revokeObjectURL(a.href)}
function completeScan(code){const person=attendees.find(a=>a.id.toLowerCase()===code.trim().toLowerCase());if(!person)s.scanResult={valid:false,used:false,name:null};else if(person.status==='Scanné')s.scanResult={valid:false,used:true,name:person.name,event:person.event};else{person.status='Scanné';s.scanResult={valid:true,used:false,name:person.name,event:person.event,type:person.type}}s.scanCode=code;render()}
function bindExperience(){document.querySelectorAll('[data-ai-search]').forEach(b=>b.onclick=()=>runEventFinder(document.querySelector('#ai-query')?.value||''));const aiInput=document.querySelector('#ai-query');if(aiInput)aiInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();runEventFinder(e.target.value)}};document.querySelectorAll('[data-discovery]').forEach(el=>el.onchange=()=>{if(el.dataset.discovery==='city')s.city=el.value;if(el.dataset.discovery==='date')s.dateRange=el.value;if(el.dataset.discovery==='budget')s.maxBudget=Number(el.value);if(el.dataset.discovery==='sort')s.sort=el.value;render();document.querySelector('#discover')?.scrollIntoView({behavior:'smooth',block:'start'})});document.querySelectorAll('[data-map-toggle]').forEach(b=>b.onclick=()=>{s.mapOpen=!s.mapOpen;render()});const mapCity=document.querySelector('[data-map-city]');if(mapCity)mapCity.onchange=e=>{s.city=e.target.value;render()};document.querySelectorAll('[data-favorite-toggle]').forEach(b=>b.onclick=()=>{const id=b.dataset.favoriteToggle;s.favoriteIds=s.favoriteIds.includes(id)?s.favoriteIds.filter(x=>x!==id):[...s.favoriteIds,id];localStorage.setItem('fodium-favorites',JSON.stringify(s.favoriteIds));render()});document.querySelectorAll('[data-join-vibe],[data-ticket-share]').forEach(b=>b.onclick=()=>shareInvite(b.dataset.ticketShare||s.event));document.querySelectorAll('[data-ticket-tab]').forEach(b=>b.onclick=()=>{s.ticketTab=b.dataset.ticketTab;render()});document.querySelectorAll('[data-ticket-open]').forEach(b=>b.onclick=()=>{s.event=b.dataset.ticketOpen;s.ticketTab='À venir';render()});document.querySelectorAll('[data-calendar-export]').forEach(b=>b.onclick=exportCalendar);document.querySelectorAll('[data-ticket-validate]').forEach(b=>b.onclick=()=>{s.validatedTicket=b.dataset.ticketValidate;render();toast('Billet validé · Animation de contrôle simulée ✓')});const scanForm=document.querySelector('#scan-form');if(scanForm)scanForm.onsubmit=e=>{e.preventDefault();completeScan(document.querySelector('#scan-input').value)};document.querySelectorAll('[data-scan-sample]').forEach(b=>b.onclick=()=>completeScan(b.dataset.scanSample));document.querySelectorAll('[data-export-csv]').forEach(b=>b.onclick=exportParticipants);const attendeeSearch=document.querySelector('[data-attendee-search]');if(attendeeSearch)attendeeSearch.oninput=e=>{s.attendeeSearch=e.target.value;const pos=e.target.selectionStart;render();const field=document.querySelector('[data-attendee-search]');field?.focus();field?.setSelectionRange(pos,pos)};const attendeeFilter=document.querySelector('[data-attendee-filter]');if(attendeeFilter)attendeeFilter.onchange=e=>{s.attendeeFilter=e.target.value;render()};document.querySelectorAll('[data-analytics]').forEach(el=>el.onchange=()=>{if(el.dataset.analytics==='period')s.period=el.value;else s.analyticsCategory=el.value;render()});document.querySelectorAll('[data-draft]').forEach(el=>{const update=()=>{const key=el.dataset.draft;s.draft[key]=key==='price'||key==='capacity'?Number(el.value):el.value;const pos=el.selectionStart;render();const next=document.querySelector(`[data-draft="${key}"]`);next?.focus();if(next&&typeof pos==='number'&&next.setSelectionRange)next.setSelectionRange(pos,pos)};el.oninput=update;el.onchange=update});document.querySelectorAll('[data-wizard]').forEach(b=>b.onclick=()=>{if(b.dataset.wizard==='next'){if(s.wizardStep===1&&!s.draft.name.trim()){toast('Ajoutez un nom pour continuer.');return}s.wizardStep=Math.min(3,s.wizardStep+1)}else if(b.dataset.wizard==='back')s.wizardStep=Math.max(1,s.wizardStep-1);else{const d=s.draft,id=`event-${Date.now()}`,dt=new Date(`${d.date}T12:00:00`);events.unshift({id,name:d.name,date:dt.toLocaleDateString('fr-FR',{day:'2-digit',month:'short'}).toUpperCase(),year:String(dt.getFullYear()),day:String(dt.getDate()).padStart(2,'0'),month:dt.toLocaleDateString('fr-FR',{month:'short'}).toUpperCase(),city:`${d.city}, Sénégal`,price:Number(d.price),category:d.category,img:events[0].img,desc:`${d.name}, un rendez-vous à ${d.city}.`});s.proPage='events';s.wizardStep=1;toast('Votre événement de démonstration est créé.')}render()});const scanInput=document.querySelector('#scan-input');if(scanInput)scanInput.oninput=e=>{s.scanCode=e.target.value}}
function initScrollMotion(){if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target)}}),{threshold:.1});document.querySelectorAll('.recommendations,.around-map,.pro-card,.insight-card,.digital-ticket').forEach(el=>{el.classList.add('scroll-reveal');observer.observe(el)})}if(!window.fodiumParallax){window.fodiumParallax=true;window.addEventListener('scroll',()=>{const hero=document.querySelector('.hero');if(hero)hero.style.setProperty('--hero-scroll',`${Math.min(24,window.scrollY*.035)}px`)},{passive:true})}}
export function finishFodiumRender(){bind();bindAssistant();bindExperience();initScrollMotion();}
